import{_ as t,o as s,c as a,a6 as o}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse('{"title":"Configuration","description":"The LCARdS Config Panel: the sidebar page for helpers, alert mode colours, HA-LCARS theme profiles, sounds, the connection overlay, users and devices, content packs and stored settings.","frontmatter":{"description":"The LCARdS Config Panel: the sidebar page for helpers, alert mode colours, HA-LCARS theme profiles, sounds, the connection overlay, users and devices, content packs and stored settings."},"headers":[],"relativePath":"configuration/index.md","filePath":"configuration/index.md","lastUpdated":1794184759000}'),r={name:"configuration/index.md"};function n(i,e,l,h,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><strong>The LCARdS Config Panel is the sidebar page where you set LCARdS up for the whole installation: its helpers, alert mode colours, sounds, the connection overlay, and the users and devices that have their own settings.</strong> The integration adds it to the sidebar as <strong>LCARdS Config</strong>.</p><ul><li>Card settings live in each card&#39;s YAML or editor. The panel holds what is shared: the Home Assistant helpers LCARdS reads, and settings stored by the integration.</li><li>Some settings can differ per user or per device (sounds, the connection overlay, theme token overrides). The panel&#39;s scope switches choose which level you are editing.</li><li>Every tab has a <strong>Docs</strong> link at its top right that opens its page here.</li></ul><div class="tip custom-block"><p class="custom-block-title">New install?</p><p>Start with <a href="./../getting-started/installation.html#_3-first-setup">First setup</a>: create the helpers, then tune alert modes and sounds.</p></div><table tabindex="0"><thead><tr><th>Page</th><th>Covers</th></tr></thead><tbody><tr><td><a href="./persistent-helpers.html">Persistent Helpers</a></td><td>Every helper LCARdS and HA-LCARS use, and how to create them by hand</td></tr><tr><td><a href="./users-devices.html">Users &amp; Devices</a></td><td>Device names and ids, and who has their own settings</td></tr><tr><td><a href="./ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a></td><td>The two LCARdS profiles HA-LCARS ships</td></tr><tr><td><a href="./ha-lcars-theme-lab.html">HA-LCARS Theme Lab</a></td><td>Building your own HA-LCARS theme profile</td></tr><tr><td><a href="./alert-mode-lab.html">Alert Mode Lab</a></td><td>How each alert mode recolours your dashboards</td></tr><tr><td><a href="./sounds.html">Sound Configuration</a></td><td>Sound schemes, categories, per-event sounds, browser autoplay</td></tr><tr><td><a href="./ha-actions.html">Home Assistant Actions</a></td><td>The <code>lcards.*</code> actions for automations and scripts</td></tr><tr><td><a href="./browser-mod.html">Using browser_mod</a></td><td>LCARdS effects next to browser_mod popups</td></tr><tr><td><a href="./connectivity.html">Connectivity</a></td><td>The overlay shown when the dashboard loses Home Assistant</td></tr></tbody></table><hr><h2 id="accessing-the-panel" tabindex="-1">Accessing the Panel <a class="header-anchor" href="#accessing-the-panel" aria-label="Permalink to &quot;Accessing the Panel&quot;">​</a></h2><p><strong>Open LCARdS Config in the Home Assistant sidebar.</strong> The integration registers it on install; there is nothing to add to your dashboards.</p><ul><li>If the entry is missing, open <strong>Settings &gt; Devices &amp; services &gt; LCARdS &gt; Configure</strong> and turn on <strong>Show sidebar panel</strong>. It appears at once, with no restart.</li><li>The same screen sets the sidebar title and icon, the log level and preview features: see <a href="./../getting-started/installation.html#integration-options">Integration options</a>.</li><li>A link can open a tab directly: <code>/lcards-config?tab=theme</code>. The tab names are <code>welcome</code>, <code>helpers</code>, <code>theme</code>, <code>connectivity</code>, <code>sounds</code>, <code>users</code>, <code>packs</code> and <code>storage</code>.</li></ul><hr><h2 id="panel-tabs" tabindex="-1">Panel Tabs <a class="header-anchor" href="#panel-tabs" aria-label="Permalink to &quot;Panel Tabs&quot;">​</a></h2><p><strong>The panel has a tab for each area.</strong> Storage shows for Home Assistant administrators only.</p><h3 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h3><p><strong>The first tab: a setup checklist, a guide to the other tabs, a health check of your installation and links.</strong></p><ul><li><strong>Get Started</strong> lists the first steps: create the helpers, customize the alert modes in the Alert Lab, customize sounds.</li><li><strong>Panel guide</strong> describes each tab; a click on one opens it.</li><li><strong>Support &amp; system info</strong> checks your setup and shows the LCARdS, integration, Home Assistant and frontend versions. <strong>Report an issue</strong> opens a pre-filled GitHub bug report for you to review (nothing is sent on its own), and <strong>Copy support info</strong> copies the same report.</li></ul><h3 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h3><p><strong>Lists every Home Assistant helper LCARdS uses, with its value and whether it exists, and creates the missing ones.</strong></p><ul><li>When any helper is missing, a banner says how many; <strong>Create All</strong> creates them all and gives each its default value. Each table row can also create one helper.</li><li>The helpers are grouped into <strong>Alert Lab Configuration</strong>, <strong>HA-LCARS Theme Settings</strong> and <strong>Sound System</strong>. <strong>Reset to Defaults</strong> on a group sets its helpers back to their default values (the sound scheme choice is left alone).</li><li>Helpers are ordinary <code>input_*</code> entities: they survive restarts and automations can read and change them. See <a href="./persistent-helpers.html">Persistent Helpers</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">First launch</p><p>Open the <strong>Helpers</strong> tab and click <strong>Create All</strong> before using anything else. This creates every helper LCARdS uses for alert mode, sounds and the alert colours, plus the HA-LCARS theme helpers, in one step.</p></div><h3 id="theme-studio" tabindex="-1">Theme Studio <a class="header-anchor" href="#theme-studio" aria-label="Permalink to &quot;Theme Studio&quot;">​</a></h3><p><strong>The theme tools, one per tab: the two labs, the token and CSS variable browsers, and token overrides.</strong></p><ul><li><strong>LCARdS Alert Mode Lab</strong>: tune how each alert mode recolours your dashboards, then save it to helpers. See <a href="./alert-mode-lab.html">Alert Mode Lab</a>.</li><li><strong>HA-LCARS Theme Lab</strong>: build your own HA-LCARS theme profile, with full palettes, LCARS chrome and state colours. See <a href="./ha-lcars-theme-lab.html">HA-LCARS Theme Lab</a>.</li><li><strong>LCARdS Theme Tokens</strong>, <strong>LCARS CSS Variables</strong> and <strong>All CSS Variables</strong> browse the active theme&#39;s tokens and the page&#39;s CSS variables: find the <code>theme:colors.ui.primary</code> path to use in card config, or the variable behind a colour.</li><li><strong>Token Overrides</strong> changes a token&#39;s value for everyone, for one user or for one device.</li></ul><p>A card editor&#39;s <strong>Main Engineering &gt; Theme</strong> tab lists the tokens that card uses and links here. See also <a href="./../core/alert-mode.html">Alert Mode</a> and <a href="./../core/themes/">Themes</a>.</p><h3 id="connectivity" tabindex="-1">Connectivity <a class="header-anchor" href="#connectivity" aria-label="Permalink to &quot;Connectivity&quot;">​</a></h3><p><strong>Sets up the full-screen overlay shown when a browser loses its connection to Home Assistant, so a kiosk never goes stale without anyone noticing.</strong></p><ul><li>The overlay can show styled text, any card, or the Borg assimilation, over effect layers you choose.</li><li>It is off until you turn it on, and can be set for everyone, one user or one device.</li></ul><p>See <a href="./connectivity.html">Connectivity</a>.</p><h3 id="sounds" tabindex="-1">Sounds <a class="header-anchor" href="#sounds" aria-label="Permalink to &quot;Sounds&quot;">​</a></h3><p><strong>Turns LCARS sounds on, picks the sound scheme and changes or mutes single events.</strong></p><ul><li>Sound categories (card interactions, UI navigation, alerts) switch groups of events on and off.</li><li>Users and devices can have their own volume, scheme and event sounds without changing the defaults.</li></ul><p>See <a href="./sounds.html">Sound Configuration</a>.</p><h3 id="users-devices" tabindex="-1">Users &amp; Devices <a class="header-anchor" href="#users-devices" aria-label="Permalink to &quot;Users &amp; Devices&quot;">​</a></h3><p><strong>Shows this browser&#39;s device name and id, and lets administrators see and tidy the users and devices that have their own settings.</strong></p><ul><li>Anyone can rename their own device here. Device names are what <a href="./ha-actions.html#targeting">targeted actions</a> use.</li><li>Administrators also see every user with stored settings and every registered device.</li></ul><p>See <a href="./users-devices.html">Users &amp; Devices</a>.</p><h3 id="pack-explorer" tabindex="-1">Pack Explorer <a class="header-anchor" href="#pack-explorer" aria-label="Permalink to &quot;Pack Explorer&quot;">​</a></h3><p><strong>Browses every content pack loaded in LCARdS and what each one adds.</strong></p><ul><li>Packs are listed with their themes, style presets, components and their presets, animations, SVG assets, fonts, sounds, images and textures.</li><li>Picking an item shows its details and, for themes, presets and SVG assets, a preview.</li></ul><h3 id="storage-advanced" tabindex="-1">Storage [advanced] <a class="header-anchor" href="#storage-advanced" aria-label="Permalink to &quot;Storage [advanced]&quot;">​</a></h3><p><strong>Shows the raw key and value store the integration keeps for LCARdS settings that are not in helpers.</strong> Visible to administrators only.</p><div class="warning custom-block"><p class="custom-block-title">Advanced: use with caution</p><p>Editing or deleting a key here changes LCARdS settings directly, with no checks. Use it to inspect or repair stored settings.</p></div><ul><li>Lists every stored key, with a JSON viewer and an editor for each value.</li><li>Deletes one key, after a confirmation, or resets the whole store, after an explicit confirmation.</li><li>Useful for debugging, recovering from a broken stored value, or seeing what per-user and per-device settings hold.</li></ul><hr><h2 id="ha-lcars-theme-profiles" tabindex="-1">HA-LCARS Theme Profiles <a class="header-anchor" href="#ha-lcars-theme-profiles" aria-label="Permalink to &quot;HA-LCARS Theme Profiles&quot;">​</a></h2><p><strong><a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a> includes two theme profiles made for LCARdS.</strong> They map the LCARdS palette onto the HA-LCARS chrome and Home Assistant&#39;s own colour tokens, so stock Home Assistant screens, LCARdS cards and the HA-LCARS chrome share one palette, alert mode colour shifts included. Pick one as your Home Assistant theme; there is nothing to install separately. See <a href="./ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>.</p>',45)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
